private static int getMaxServings(int[] stock, int[] dish) {
    int maxServings = Integer.MAX_VALUE;
    for (int i = 0; i < stock.length; i++) {
        if (dish[i] > 0) {
            maxServings = Math.min(maxServings, stock[i] / dish[i]);
        }
    }
    return maxServings;
}

private static int getMaxServingsWithRemaining(int[] stock, int[] A, int[] B, int servingsA) {
